"""ExecuTorch parity harness: golden PyTorch reference vs .pte, same numbers.

Runs block-by-block with explicit state feedback against the golden vectors
generated by make_golden.py (from the proven wrappers).
Run inside venv-et.
"""
import json
import sys
import time
from pathlib import Path

import numpy as np
import torch

HERE = Path(__file__).resolve().parent
META = json.loads((HERE / "models" / "rave_meta.json").read_text())
G = np.load(HERE / "golden" / "golden.npz")
BLOCK = int(G["block_size"])
N_BLOCKS = int(G["n_blocks"])
N_FRAMES = int(G["n_frames"])
TOL = 1e-5

from executorch.runtime import Runtime

torch.set_grad_enabled(False)


def load_method(name):
    rt = Runtime.get()
    program = rt.load_program(str(HERE / "models" / name))
    return program.load_method("forward")


def report(name, ref, out, tol=TOL):
    ref, out = np.asarray(ref), np.asarray(out)
    diff = np.abs(ref - out).max()
    scaled = diff / (1.0 + np.abs(ref).max())
    status = "OK " if scaled < tol else "FAIL"
    print(f"[{status}] {name:<46} max diff {diff:.3e} "
          f"(scaled {scaled:.3e}, tol {tol:g})")
    assert scaled < tol, name


def audio_block(arr, i):
    return torch.from_numpy(arr[..., i * BLOCK:(i + 1) * BLOCK].copy())


def run_forward(method, audio, fills, state_size):
    state = torch.zeros(1, state_size)
    out = []
    for i in range(N_BLOCKS):
        y, state = method.execute(
            [audio_block(audio, i), state, torch.from_numpy(fills[i].copy())])
        out.append(y.numpy())
    return np.concatenate(out, -1)


def main():
    m_fwd = load_method("rave_forward.pte")
    m_enc = load_method("rave_encoder.pte")
    m_dec = load_method("rave_decoder.pte")
    sizes = META["state_sizes"]

    # forward parity
    out = run_forward(m_fwd, G["audio"], G["fill_fwd"], sizes["forward"])
    report("forward: executorch vs TorchScript", G["forward_ref"], out)

    # encoder parity
    state = torch.zeros(1, sizes["encoder"])
    z_out = []
    for i in range(N_BLOCKS):
        z, state = m_enc.execute([audio_block(G["audio"], i), state])
        z_out.append(z.numpy())
    z_out = np.concatenate(z_out, -1)
    report("encoder: executorch vs TorchScript", G["latent_ref"], z_out)

    # decoder parity (golden latents in, golden audio out)
    state = torch.zeros(1, sizes["decoder"])
    y_out = []
    for i in range(N_BLOCKS):
        z = torch.from_numpy(
            G["latent_ref"][..., i * N_FRAMES:(i + 1) * N_FRAMES].copy())
        y, state = m_dec.execute(
            [z, state, torch.from_numpy(G["fill_dec"][i].copy())])
        y_out.append(y.numpy())
    report("decoder: executorch vs TorchScript", G["decoder_ref"],
           np.concatenate(y_out, -1))

    # state isolation: two different streams interleaved through ONE method
    sa = torch.zeros(1, sizes["forward"])
    sb = torch.zeros(1, sizes["forward"])
    out_a, out_b = [], []
    for i in range(N_BLOCKS):
        ya, sa = m_fwd.execute([audio_block(G["audio"], i), sa,
                                torch.from_numpy(G["fill_fwd"][i].copy())])
        yb, sb = m_fwd.execute([audio_block(G["audio_b"], i), sb,
                                torch.from_numpy(G["fill_fwd_b"][i].copy())])
        out_a.append(ya.numpy())
        out_b.append(yb.numpy())
    report("interleaved stream A (one method)", G["forward_ref"],
           np.concatenate(out_a, -1))
    report("interleaved stream B (one method)", G["forward_ref_b"],
           np.concatenate(out_b, -1))

    # benchmark
    args = [audio_block(G["audio"], 0), torch.zeros(1, sizes["forward"]),
            torch.from_numpy(G["fill_fwd"][0].copy())]
    for _ in range(5):
        m_fwd.execute(args)
    t0 = time.perf_counter()
    n_iter = 50
    for _ in range(n_iter):
        m_fwd.execute(args)
    dt = (time.perf_counter() - t0) / n_iter * 1000
    budget = BLOCK / META["sample_rate"] * 1000
    print(f"\nbenchmark: {dt:.2f} ms per {BLOCK}-sample block "
          f"(realtime budget {budget:.2f} ms, {budget / dt:.1f}x realtime)")
    print("ALL OK")


if __name__ == "__main__":
    main()
